package com.jobradar.taxonomy.role;import com.jobradar.common.api.*;import com.jobradar.common.pagination.PaginationParameters;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController public class RoleController{private final RoleService s;public RoleController(RoleService s){this.s=s;}@GetMapping("/api/v1/roles")public ApiResponse<PaginatedResponse<RoleDto>> list(@RequestParam(required=false)String search,@RequestParam(required=false)Integer categoryId,@Valid @ModelAttribute PaginationParameters p){return ApiResponse.success("Job roles retrieved successfully",s.browse(search,categoryId,p));}@GetMapping("/api/v1/roles/{slug}")public ApiResponse<RoleDto> get(@PathVariable String slug){return ApiResponse.success("Job role retrieved successfully",s.bySlug(slug));}@PostMapping("/api/v1/admin/roles")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<RoleDto> create(@Valid @RequestBody RoleRequest r){return ApiResponse.success("Job role created successfully",s.create(r));}@PutMapping("/api/v1/admin/roles/{id}")public ApiResponse<RoleDto> update(@PathVariable Integer id,@Valid @RequestBody RoleRequest r){return ApiResponse.success("Job role updated successfully",s.update(id,r));}@PatchMapping("/api/v1/admin/roles/{id}/{state:activate|deactivate}")public ApiResponse<Void> active(@PathVariable Integer id,@PathVariable String state){s.active(id,state.equals("activate"));return ApiResponse.success("Job role status updated successfully",null);}}
